from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(13,'angles','Les angles','3 · Grandeurs et mesures',
'Comparer · Reporter · Sommes · L’angle droit vaut 90°',
['Comparer et reproduire des angles avec un calque.','Construire la somme ou un multiple d’angles donnés.','Utiliser la mesure de l’angle droit : 90 degrés.'],
['Angles comparés au CM1 et équerre.'],[
page(1,'Comparer et reproduire',
bloc('definition',r'Un angle est l’écartement entre deux côtés issus d’un même sommet. L’angle de sommet B dont les côtés passent par A et C se note $\widehat{ABC}$ : la lettre du sommet au milieu. La longueur dessinée des côtés ne change pas l’angle.'),
r'@FIG:cours-angle-calque@',
bloc('savoirfaire',r'Pour comparer ou reproduire un angle : le décalquer, puis poser le calque sommet sur sommet, un côté sur un côté. L’angle le plus ouvert est le plus grand. Pour reporter, tracer le long des deux côtés du calque.','Le calque, outil des angles'),
bloc('propriete',r'L’angle droit est le repère central : l’équerre le vérifie. Un angle peut être plus petit, égal ou plus grand qu’un angle droit ; au cours moyen, on travaille avec des angles saillants, au plus égaux à l’angle plat.')),
page(2,'Sommes, multiples et degrés',
bloc('definition',r'Les angles se mesurent en degrés. Un angle droit mesure $90^\circ$. Deux angles droits mis côte à côte forment un angle plat : $90+90=180^\circ$. Le rapporteur, lui, sera utilisé au collège.'),
bloc('savoirfaire',r'Construire la somme de deux angles : reporter le premier, puis reporter le second contre un côté du premier, sommets superposés. Le double d’un angle s’obtient en le reportant deux fois.','Juxtaposer pour additionner'),
bloc('exemple',r'La moitié d’un angle droit, obtenue par pliage, mesure $90:2=45^\circ$. Un angle droit et sa moitié mis bout à bout mesurent $90+45=135^\circ$. Les moitiés et les sommes donnent des mesures sans instrument.'),
bloc('attention',r'Partager un angle en parts égales se fait par pliage du calque, pas à l’œil. Et une mesure annoncée se contrôle : un angle « de 90 degrés » doit accepter l’équerre exactement.'))
],[
E('Nommer et décrire',r'Nommer l’angle marqué sur la figure, donner son sommet et ses côtés.',r'C’est l’angle $\widehat{ABC}$ : sommet $\res B$, côtés passant par A et par C. La lettre du sommet s’écrit au milieu.','Repérer le sommet d’abord.','assert 1==1',figure='ang-1'),
E('Comparer au calque',r'Ranger les trois angles dessinés du plus fermé au plus ouvert.',r'Le calque superposé donne $\res{\widehat B<\widehat A<\widehat C}$. Les longueurs des côtés dessinés ne comptent pas.','Superposer sommet et un côté.','assert 25<50<105',figure='ang-2'),
E('Reproduire un angle',r'Reproduire l’angle donné à l’aide d’un calque, à partir de la demi-droite déjà tracée.',r'On décalque l’angle, on pose le calque sur la demi-droite, sommet sur le point marqué, puis on trace le second côté. La reproduction figure en vert.','Garder le calque bien calé pendant le tracé.','assert 1==1',figure='ang-3'),
E('La chasse aux angles droits',r'Avec l’équerre, repérer les angles droits du quadrilatère dessiné.',r'L’équerre s’ajuste en $\res A$ et en $\res D$ : deux angles droits, codés d’un petit carré. Les deux autres angles ne conviennent pas.','Tester chaque sommet à l’équerre.','assert 2<=4',figure='ang-4'),
E('90 degrés',r'Un angle droit mesure 90 degrés. Que mesure un angle plat ? Et la moitié d’un angle droit ?',r'L’angle plat vaut deux droits : $90+90=\res{180^\circ}$. La moitié d’un droit vaut $90:2=\res{45^\circ}$.','Composer à partir de 90.','assert 90+90==180 and 90//2==45'),
E('La somme de deux angles',r'Construire un angle égal à la somme des deux angles donnés, puis dire s’il dépasse un angle droit.',r'On reporte le second angle contre un côté du premier, sommets superposés. La somme, en vert, est $\res{\text{plus ouverte qu’un angle droit}}$ : l’équerre ne la couvre pas ; ici $55+45=100>90$.','Juxtaposer sans chevaucher.','assert 55+45==100 and 100>90',figure='ang-6'),
E('Le double',r'Construire le double de l’angle donné. S’il mesure 35 degrés, que mesure son double ?',r'On reporte l’angle deux fois côte à côte : le double figure en vert et mesure $35\times2=\res{70^\circ}$, encore plus petit qu’un angle droit.','Reporter deux fois avec le calque.','assert 35*2==70 and 70<90',figure='ang-7'),
E('La moitié par pliage',r'Comment obtenir la moitié de l’angle dessiné sans instrument de mesure ? Si l’angle est droit, que mesure sa moitié ?',r'On plie le calque de l’angle en amenant un côté exactement sur l’autre : le pli donne la moitié, en vert. Pour un angle droit : $\res{45^\circ}$.','Amener côté sur côté par pliage.','assert 90//2==45',figure='ang-8'),
E('Des mesures sans rapporteur',r'Donner la mesure : d’un angle droit et demi ; de trois moitiés d’angle droit ; d’un angle plat moins un angle droit.',r'$90+45=\res{135^\circ}$ ; $45\times3=\res{135^\circ}$ aussi ; $180-90=\res{90^\circ}$ : un angle droit.','Composer avec 90 et 45.','assert 90+45==135 and 45*3==135 and 180-90==90'),
E('Ranger des angles',r'Ranger les quatre angles dessinés du plus petit au plus grand, en utilisant l’angle droit comme repère.',r'$\widehat D$ est plus petit qu’un droit, $\widehat A$ est droit, $\widehat C$ dépasse le droit, $\widehat B$ est presque plat : $\res{\widehat D<\widehat A<\widehat C<\widehat B}$.','Situer chaque angle par rapport à 90°.','assert 40<90<120<170',figure='ang-10'),
E('Les aiguilles de l’horloge',r'À quelles heures piles les aiguilles d’une horloge forment-elles un angle droit ? Quel angle forment-elles à 6 h ?',r'À $\res{3\ \text h}$ et à $\res{9\ \text h}$, les aiguilles forment un angle droit. À 6 h, elles sont opposées : un angle $\res{\text{plat}}$, de 180 degrés.','Imaginer le cadran et les quarts de tour.','assert 3*30==90 and 9*30==270 and 360-270==90 and 6*30==180',figure='ang-11'),
E('L’éventail',r'Un éventail déplié forme un angle plat, partagé en 4 secteurs identiques. Quelle est la mesure de l’angle de chaque secteur ?',r'$180:4=\res{45^\circ}$ : chaque secteur vaut la moitié d’un angle droit. Contrôle : $4\times45=180$.','Partager 180 en parts égales.','assert 180//4==45 and 4*45==180',figure='ang-13'),
E('Le toit de la cabane',r'Les deux pans du toit forment ensemble un angle droit au faîte, et sont également inclinés. Quel angle chaque pan fait-il avec la ligne du faîte ?',r'L’angle droit se partage en deux angles égaux : $90:2=\res{45^\circ}$ chacun. Le pliage du calque confirmerait l’égalité.','Partager l’angle droit en deux.','assert 90//2==45',figure='ang-14'),
E('Des côtés trompeurs',r'Zina affirme : « L’angle E est plus grand que l’angle F, ses côtés sont plus longs. » Corriger en comparant au calque.',r'L’ouverture seule compte : le calque montre $\res{\widehat E<\widehat F}$ malgré ses longs côtés dessinés. Un angle n’est pas une surface ni une longueur.','Comparer les écartements au calque.','assert 30<60',figure='ang-15'),
E('Le programme d’angles',r'Exécuter : tracer une demi-droite ; reporter un angle droit ; contre lui, reporter la moitié d’un angle droit. Quelle est la mesure de l’angle total obtenu ?',r'L’angle total juxtapose $90^\circ$ et $45^\circ$ : il mesure $90+45=\res{135^\circ}$. La construction, au calque et à l’équerre, figure en vert.','Additionner les mesures reportées.','assert 90+45==135',figure='ang-9')
],reperes=['Vocabulaire et comparaisons','Reports et reproductions','Sommes, doubles et moitiés','L’angle droit et ses 90 degrés'],deco='grandeurs')

chapitre(14,'durees','Durées : jusqu’à la seconde','3 · Grandeurs et mesures',
'Heures · Minutes · Secondes · Calculs d’instants',
['Convertir entre heures, minutes et secondes.','Calculer une durée, un début ou une fin d’évènement.','Résoudre des problèmes de temps en plusieurs étapes.'],
['Durées en heures et minutes du CM1.'],[
page(1,'La seconde entre en scène',
bloc('definition',r'Une minute vaut 60 secondes et une heure vaut 60 minutes, donc une heure vaut $60\times60=3\,600$ secondes. Les durées s’écrivent en heures, minutes et secondes : 1 h 24 min 35 s.'),
bloc('savoirfaire',r'Convertir : 2 min 15 s $=120+15=135$ s ; 200 s $=180+20=3$ min 20 s. Pour les heures : 1 h 12 min $=72$ min ; 100 min $=1$ h 40 min. On échange toujours des paquets de 60.','Des paquets de 60'),
bloc('exemple',r'Le chronomètre affiche souvent les secondes : au 100 mètres, 58 s contre 1 min 01 s, c’est 58 contre 61 : trois secondes d’écart. En natation, 1 min 24 s 5 dixièmes se lit aussi 84,5 secondes.'),
bloc('attention',r'Un horaire est un instant, une durée est un temps écoulé : 60 minutes font une heure, jamais « 100 minutes » dans une heure. Le système du temps est en base 60, pas en base 10.')),
page(2,'Calculer avec les durées',
bloc('savoirfaire',r'Durée entre deux instants : avancer par étapes. De 10 h 47 min 30 s à 11 h 02 min 10 s : 12 min 30 s pour atteindre 11 h, puis 2 min 10 s : total 14 min 40 s.','Avancer par étapes rondes'),
bloc('exemple',r'Additionner des durées : 2 min 40 s $+$ 1 min 35 s $=3$ min 75 s $=4$ min 15 s : les 75 secondes s’échangent contre 1 min 15 s. La retenue vaut 60, pas 100.'),
bloc('propriete',r'Heure de fin $=$ heure de début $+$ durée ; heure de début $=$ heure de fin $-$ durée. Une frise des instants évite les erreurs de sens.'),
bloc('attention',r'Comparer des durées exige la même unité : 1 min 30 s et 95 s se comparent en secondes ($90<95$). Les dixièmes de seconde départagent les courses serrées.'))
],[
E('Convertir en secondes',r'Convertir : 2 min ; 2 min 15 s ; 5 min 08 s.',r'$2\times60=\res{120}$ s ; $120+15=\res{135}$ s ; $5\times60+8=\res{308}$ s.','Compter 60 secondes par minute.','assert 2*60==120 and 120+15==135 and 5*60+8==308'),
E('Convertir en minutes et secondes',r'Convertir en minutes et secondes : 200 s ; 428 s ; 59 s ; 60 s.',r'$200=3\times60+20$ : $\res{3\ \text{min}\ 20\ \text s}$. $428=7\times60+8$ : $\res{7\ \text{min}\ 08\ \text s}$. 59 s reste 59 s ; 60 s font $\res{1\ \text{min}}$ exactement.','Extraire les paquets de 60.','assert divmod(200,60)==(3,20) and divmod(428,60)==(7,8) and 60==60'),
E('L’heure en secondes',r'Combien de secondes dans une heure ? Dans un quart d’heure ?',r'$60\times60=\res{3\,600}$ s. Un quart d’heure : $3\,600:4=\res{900}$ s, soit 15 minutes.','Multiplier les paquets de 60.','assert 60*60==3600 and 3600//4==900'),
E('Additionner des durées',r'Calculer : 2 min 40 s $+$ 1 min 35 s, puis 3 h 45 min $+$ 2 h 30 min.',r'$2$ min 40 s $+1$ min 35 s $=3$ min 75 s $=\res{4\ \text{min}\ 15\ \text s}$. Et $3$ h 45 $+2$ h 30 $=5$ h 75 min $=\res{6\ \text h\ 15}$.','Échanger 60 unités contre une du rang supérieur.','assert (2*60+40)+(1*60+35)==255 and divmod(255,60)==(4,15) and (3*60+45)+(2*60+30)==375 and divmod(375,60)==(6,15)'),
E('Le chrono du 100 m',r'Aux essais, Lina court le 100 m en 1 min 01 s et Noa en 58 s. Qui est le plus rapide, et de combien ?',r'$1$ min 01 s $=61$ s : $\res{\text{Noa}}$ gagne, avec $61-58=\res3$ s d’avance.','Tout convertir en secondes.','assert 60+1==61 and 61-58==3'),
E('La durée du trajet',r'Un métro part à 10 h 47 min 30 s et arrive à 11 h 02 min 10 s. Combien dure le trajet ?',r'Jusqu’à 11 h : 12 min 30 s ; puis 2 min 10 s : total $\res{14\ \text{min}\ 40\ \text s}$.','Faire étape à l’heure ronde.','assert (11*3600+2*60+10)-(10*3600+47*60+30)==880 and 14*60+40==880'),
E('L’heure de fin',r'Un lavage de voiture commence à 9 h 52 et dure 25 min. Un cycle de machine commence à 17 h 48 min 30 s et dure 1 min 40 s. Donner les deux heures de fin.',r'$9$ h $52+8$ min $=10$ h, puis 17 min : $\res{10\ \text h\ 17}$. Pour la machine : 30 s mènent à 17 h 49, puis 1 min 10 s : $\res{17\ \text h\ 50\ \text{min}\ 10\ \text s}$.','Compléter d’abord la minute ou l’heure entamée.','assert (9*60+52)+25==10*60+17 and (17*3600+48*60+30)+100==17*3600+50*60+10'),
E('Remonter le temps',r'Un gâteau doit sortir du four à 18 h 10 après 35 min de cuisson. À quelle heure faut-il l’enfourner ?',r'On recule : 10 min ramènent à 18 h, puis 25 min : enfourner à $\res{17\ \text h\ 35}$. Contrôle : $17$ h $35+35$ min $=18$ h 10.','Soustraire par étapes depuis la fin.','assert (18*60+10)-35==17*60+35'),
E('Comparer des durées',r'Quelle durée est la plus longue : 1 min 30 s ou 95 s ? Et 2 h 05 ou 118 min ?',r'$1$ min 30 s $=90$ s $<95$ s : $\res{95\ \text s}$ gagne. $2$ h 05 $=125$ min $>118$ min : $\res{2\ \text h\ 05}$ est plus longue.','Convertir dans la même unité.','assert 90<95 and 125>118'),
E('Les dixièmes qui décident',r'En natation, Aya réalise $32{,}6$ s et Lou $32{,}48$ s. Qui touche le mur la première ? Quel est l’écart ?',r'$32{,}48<32{,}60$ : $\res{\text{Lou}}$ gagne. Écart : $32{,}6-32{,}48=\res{0{,}12}$ s, douze centièmes de seconde.','Comparer les décimales des secondes.','assert Rational("32.48")<Rational("32.6") and Rational("32.6")-Rational("32.48")==Rational(".12")'),
E('La playlist',r'Une chanson dure 3 min 45 s. Quelle est la durée de 4 écoutes ? Cette durée dépasse-t-elle un quart d’heure ?',r'$3$ min 45 s $=225$ s ; $225\times4=900$ s $=\res{15\ \text{min}}$ exactement : le quart d’heure est atteint, $\res{\text{pas dépassé}}$.','Multiplier en secondes puis reconvertir.','assert (3*60+45)*4==900 and 900==15*60'),
E('Le tour de circuit',r'Un kart boucle un tour en 1 min 12 s. Combien de temps durent 5 tours ? Et combien de tours complets en 10 minutes ?',r'$72\times5=360$ s $=\res{6\ \text{min}}$. En 600 s : $600=72\times8+24$, soit $\res8$ tours complets et 24 s entamées.','Travailler en secondes.','assert 72*5==360 and divmod(600,72)==(8,24)'),
E('La séance bien remplie',r'Un cours de sport de 1 h 30 comprend 12 min d’échauffement, 55 min de jeu et des étirements pour finir. Combien de temps durent les étirements ?',r'$1$ h 30 $=90$ min ; $90-12-55=\res{23}$ min d’étirements.','Soustraire les parties connues du total.','assert 90-12-55==23'),
E('Le journal de bord',r'Un randonneur marche de 9 h 40 à 12 h 05, s’arrête 45 min, puis marche de 12 h 50 à 15 h 10. Quelle est sa durée totale de marche ?',r'Matin : de 9 h 40 à 12 h 05, soit 2 h 25. Après-midi : de 12 h 50 à 15 h 10, soit 2 h 20. Total : $2$ h $25+2$ h $20=\res{4\ \text h\ 45}$ de marche.','Calculer chaque tronçon puis additionner.','assert (12*60+5)-(9*60+40)==145 and (15*60+10)-(12*60+50)==140 and 145+140==285 and divmod(285,60)==(4,45)'),
E('Vrai ou faux ?',r'Tom écrit : « 1 h 85 min, c’est une durée correcte » et « 2 min 30 s $=$ 2,3 min ». Corriger ces deux écritures.',r'$85$ min dépassent l’heure : 1 h 85 min $=\res{2\ \text h\ 25}$. Et 30 s font une demi-minute : 2 min 30 s $=\res{2{,}5}$ min, pas $2{,}3$. Le temps compte en base 60.','Échanger les paquets de 60, pas de 100.','assert 60+85==145 and divmod(145,60)==(2,25) and Rational(30,60)==Rational(".5")')
],reperes=['Secondes et conversions','Sommes et retenues en base 60','Instants, débuts et fins','Chronos et problèmes'],deco='grandeurs')
